// ConcTypeOptionTypeOptionList is the term type of the variadic operator `concTypeOption(...)` of sort TypeOptionList
// (Java's abstract class concTypeOption): a maximally-shared cons cell (Java's
// ConsconcTypeOption: a head and a tail) or the empty list (Java's EmptyconcTypeOption).
type ConcTypeOptionTypeOptionList struct {
	head  TypeOption
	tail  TypeOptionList
	empty bool
	hash  uint32
	// children caches the Visitable children (Java's children field)
	children atomic.Pointer[[]any]
}

func (*ConcTypeOptionTypeOptionList) isTypeOptionList() {}

func (t *ConcTypeOptionTypeOptionList) Hash() uint32 { return t.hash }

func (t *ConcTypeOptionTypeOptionList) Equivalent(other sharedobjects.Term) bool {
	o, ok := other.(*ConcTypeOptionTypeOptionList)
	return ok && t.empty == o.empty && t.head == o.head && t.tail == o.tail
}

func (t *ConcTypeOptionTypeOptionList) Duplicate() sharedobjects.Term {
	return &ConcTypeOptionTypeOptionList{head: t.head, tail: t.tail, empty: t.empty, hash: t.hash}
}

// elements returns the cached Visitable children of the list: its
// elements (Java's getChildren, i.e. toArray).
// Java's getChildren is the typed toArray(new TypeOption[]{}): a last tail
// that is not a list (of sort TypeOptionList) cannot be stored in it
// (ArrayStoreException, a *aterm.GomError here).
func (t *ConcTypeOptionTypeOptionList) elements() []any {
	if c := t.children.Load(); c != nil {
		return *c
	}
	var cur TypeOptionList = t
	for {
		c, ok := cur.(*ConcTypeOptionTypeOptionList)
		if !ok || c.empty {
			break
		}
		cur = c.tail
	}
	if c, ok := cur.(*ConcTypeOptionTypeOptionList); !ok || !c.empty {
		panic(&aterm.GomError{Msg: fmt.Sprintf("ArrayStoreException: the tail %v of a concTypeOption list is not a TypeOption", cur)})
	}
	c := t.ToArray()
	t.children.Store(&c)
	return c
}

func (t *ConcTypeOptionTypeOptionList) ChildCount() int { return len(t.elements()) }

func (t *ConcTypeOptionTypeOptionList) ChildAt(i int) any { return t.elements()[i] }

func (t *ConcTypeOptionTypeOptionList) SetChildAt(i int, child any) any {
	dup := t.Children()
	dup[i] = child
	return t.SetChildren(dup)
}

func (t *ConcTypeOptionTypeOptionList) Children() []any { return append([]any(nil), t.elements()...) }

// SetChildren is Java's setChildren of a list: ConcTypeOptionFromArray(children).
func (t *ConcTypeOptionTypeOptionList) SetChildren(children []any) any {
	args := make([]TypeOption, len(children))
	for i, c := range children {
		args[i] = c.(TypeOption)
	}
	return MakeConcTypeOption(args...)
}

func (t *ConcTypeOptionTypeOptionList) String() string {
	var b strings.Builder
	b.WriteString("concTypeOption(")
	var cur TypeOptionList = t
	for {
		c, ok := cur.(*ConcTypeOptionTypeOptionList)
		if !ok {
			b.WriteString("," + fmt.Sprint(cur))
			break
		}
		if c.empty {
			break
		}
		if c != t {
			b.WriteString(",")
		}
		b.WriteString(fmt.Sprint(c.head))
		cur = c.tail
	}
	b.WriteString(")")
	return b.String()
}

// RealMakeConsConcTypeOption is Java Gom's ConsconcTypeOption.realMake: the shared cell of head
// and tail, without hook.
func RealMakeConsConcTypeOption(head TypeOption, tail TypeOptionList) TypeOptionList {
	proto := &ConcTypeOptionTypeOptionList{head: head, tail: tail, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("ConsconcTypeOption"), []uint32{head.Hash(), tail.Hash()})}
	return factory.Build(proto).(*ConcTypeOptionTypeOptionList)
}

// realMakeEmptyConcTypeOption is Java Gom's EmptyconcTypeOption.realMake: the shared empty list,
// without hook.
func realMakeEmptyConcTypeOption() TypeOptionList {
	proto := &ConcTypeOptionTypeOptionList{empty: true, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("EmptyconcTypeOption"), nil)}
	return factory.Build(proto).(*ConcTypeOptionTypeOptionList)
}

// RawConcTypeOption builds the concTypeOption list holding exactly args, without construction
// hook.
func RawConcTypeOption(args ...TypeOption) TypeOptionList {
	l := realMakeEmptyConcTypeOption()
	for i := len(args) - 1; i >= 0; i-- {
		l = RealMakeConsConcTypeOption(args[i], l)
	}
	return l
}

