// elements returns the cached Visitable children of the list: its
// elements (Java's getChildren, i.e. toArray).
// Java's getChildren is the typed toArray(new TomType[]{}): a last tail
// that is not a list (of sort TomTypeList) cannot be stored in it
// (ArrayStoreException, a *aterm.GomError here).
func (t *ConcTomTypeTomTypeList) elements() []any {
	if c := t.children.Load(); c != nil {
		return *c
	}
	var cur TomTypeList = t
	for {
		c, ok := cur.(*ConcTomTypeTomTypeList)
		if !ok || c.empty {
			break
		}
		cur = c.tail
	}
	if c, ok := cur.(*ConcTomTypeTomTypeList); !ok || !c.empty {
		panic(&aterm.GomError{Msg: fmt.Sprintf("ArrayStoreException: the tail %v of a concTomType list is not a TomType", cur)})
	}
	c := t.ToArray()
	t.children.Store(&c)
	return c
}

func (t *ConcTomTypeTomTypeList) ChildCount() int { return len(t.elements()) }

func (t *ConcTomTypeTomTypeList) ChildAt(i int) any { return t.elements()[i] }

func (t *ConcTomTypeTomTypeList) SetChildAt(i int, child any) any {
	dup := t.Children()
	dup[i] = child
	return t.SetChildren(dup)
}

func (t *ConcTomTypeTomTypeList) Children() []any { return append([]any(nil), t.elements()...) }

// SetChildren is Java's setChildren of a list: ConcTomTypeFromArray(children).
func (t *ConcTomTypeTomTypeList) SetChildren(children []any) any {
	args := make([]TomType, len(children))
	for i, c := range children {
		args[i] = c.(TomType)
	}
	return MakeConcTomType(args...)
}

func (t *ConcTomTypeTomTypeList) String() string {
	var b strings.Builder
	b.WriteString("concTomType(")
	var cur TomTypeList = t
	for {
		c, ok := cur.(*ConcTomTypeTomTypeList)
		if !ok {
			b.WriteString("," + fmt.Sprint(cur))
			break
		}
		if c.empty {
			break
		}
		if c != t {
			b.WriteString(",")
		}
		b.WriteString(fmt.Sprint(c.head))
		cur = c.tail
	}
	b.WriteString(")")
	return b.String()
}

// RealMakeConsConcTomType is Java Gom's ConsconcTomType.realMake: the shared cell of head
// and tail, without hook.
func RealMakeConsConcTomType(head TomType, tail TomTypeList) TomTypeList {
	proto := &ConcTomTypeTomTypeList{head: head, tail: tail, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("ConsconcTomType"), []uint32{head.Hash(), tail.Hash()})}
	return factory.Build(proto).(*ConcTomTypeTomTypeList)
}

// realMakeEmptyConcTomType is Java Gom's EmptyconcTomType.realMake: the shared empty list,
