// ToATerm is Java's toATerm: the list of the elements, ending with the
// ATerm list of the tail (a tail that is not a list is Java's
// ClassCastException).
func (t *ConcTomTypeTomTypeList) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	var heads []TomType
	var cur TomTypeList = t
	for {
		c, ok := cur.(*ConcTomTypeTomTypeList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	l := f.MakeListEmpty()
	if c, ok := cur.(*ConcTomTypeTomTypeList); !ok || !c.empty {
		tl, isList := cur.ToATerm().(*aterm.ATermList)
		if !isList {
			panic(&aterm.GomError{Msg: fmt.Sprintf("ClassCastException: the ATerm of %v is not an ATermList", cur)})
		}
		l = tl
	}
	for i := len(heads) - 1; i >= 0; i-- {
		l = f.MakeList(heads[i].ToATerm(), l)
	}
	return l
}

// fromTermConcTomTypeTomTypeList is Java Gom's concTomType.fromTerm: an application of concTomType, or a
// list (of ToATerm), of convertible elements.
func fromTermConcTomTypeTomTypeList(trm aterm.ATerm, conv aterm.ATermConverter) (res TomTypeList, ok bool) {
	trm = conv.Convert(trm)
	if appl, isAppl := trm.(*aterm.ATermAppl); isAppl && appl.GetName() == "concTomType" {
		elems := make([]TomType, appl.GetArity())
		for i, a := range appl.GetArguments() {
			elems[i] = TomTypeFromTermConv(a, conv)
		}
		return MakeConcTomType(elems...), true
	}
	if list, isList := trm.(*aterm.ATermList); isList {
		// an element that cannot be converted: not a concTomType (Java returns null)
		defer func() {
			if recover() != nil {
				res, ok = nil, false
			}
		}()
		var elems []TomType
		for !list.IsEmpty() {
			elems = append(elems, TomTypeFromTermConv(list.GetFirst(), conv))
			list = list.GetNext()
		}
		return MakeConcTomType(elems...), true
	}
	return nil, false
}
